CREATE TABLE IF NOT EXISTS `dpn_medical_radiology_orders` (`id` bigint unsigned NOT NULL AUTO_INCREMENT,`patient_cid` varchar(64) NOT NULL,`ordered_by` varchar(64) NOT NULL,`study_type` varchar(32) NOT NULL,`body_part` varchar(32) NULL,`status` varchar(32) NOT NULL,`findings` text NULL,`created_at` timestamp NOT NULL DEFAULT current_timestamp(),PRIMARY KEY (`id`),KEY `idx_radiology_patient` (`patient_cid`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
